function summarizeWindow(events, nowMs, windowMs, cap) {
  const list = Array.isArray(events) ? events : [];

  // Step 2: deduplicate raw events by non-empty string id, keeping the FIRST
  // occurrence in input order, then apply the qualification filter.
  const seen = new Set();
  const deduped = [];
  for (const ev of list) {
    if (ev && typeof ev === 'object') {
      const id = ev.id;
      if (typeof id === 'string' && id !== '') {
        if (seen.has(id)) continue;
        seen.add(id);
      }
    }
    deduped.push(ev);
  }

  const lo = nowMs - windowMs;
  const qualifying = deduped.filter((ev) => {
    if (!ev || typeof ev !== 'object') return false;
    // window [nowMs - windowMs, nowMs], both endpoints inclusive
    if (typeof ev.ts !== 'number' || !Number.isFinite(ev.ts)) return false;
    if (ev.ts < lo || ev.ts > nowMs) return false;
    // provider
    if (ev.provider !== 'opencode-go') return false;
    // rejected / unbilled rows are ignored
    if (ev.error) return false;
    // free-pool rows never burn Go quota
    if (typeof ev.model !== 'string') return false;
    if (ev.model.toLowerCase().endsWith('-free')) return false;
    return true;
  });

  const used = qualifying.length;
  const capNum = typeof cap === 'number' && Number.isFinite(cap) && cap > 0 ? cap : 1;
  const remaining = Math.max(0, cap - used);
  const pct = Math.round((used / capNum) * 1000) / 10;
  const overCap = used > cap;

  let oldestExpiresAt = null;
  if (used > 0) {
    let minTs = Infinity;
    for (const ev of qualifying) {
      if (ev.ts < minTs) minTs = ev.ts;
    }
    oldestExpiresAt = minTs + windowMs;
  }

  const counts = {};
  for (const ev of qualifying) {
    let name = ev.model;
    if (name.toLowerCase().startsWith('opencode-go/')) {
      name = name.slice('opencode-go/'.length);
    }
    name = name.toLowerCase();
    counts[name] = (counts[name] || 0) + 1;
  }
  const byModel = {};
  for (const key of Object.keys(counts).sort()) {
    byModel[key] = counts[key];
  }

  return { used, remaining, pct, overCap, oldestExpiresAt, byModel };
}
